//#region src/core/utils.ts
const TAU = Math.PI * 2;
/** 俯视地面的纵向压扁系数，越小越"斜视角" */
const YSQUASH = .62;
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp = (a, b, t) => a + (b - a) * t;
/** 帧率无关的指数趋近 */
const damp = (a, b, rate, dt) => lerp(a, b, 1 - Math.exp(-rate * dt));
const rand = (a, b) => a + Math.random() * (b - a);
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
const chance = (p) => Math.random() < p;
const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
const dist2 = (ax, ay, bx, by) => {
	const dx = bx - ax, dy = by - ay;
	return dx * dx + dy * dy;
};
const angleTo = (ax, ay, bx, by) => Math.atan2(by - ay, bx - ax);
/** 归一化到 [-PI, PI] 的角度差 */
function angleDiff(a, b) {
	let d = (b - a) % TAU;
	if (d > Math.PI) d -= TAU;
	if (d < -Math.PI) d += TAU;
	return d;
}
/** 确定性随机（关卡布局用，保证每次一样） */
function mulberry32(seed) {
	let a = seed >>> 0;
	return function() {
		a |= 0;
		a = a + 1831565813 | 0;
		let t = Math.imul(a ^ a >>> 15, 1 | a);
		t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
		return ((t ^ t >>> 14) >>> 0) / 4294967296;
	};
}
/** 屏幕坐标 → 地面世界坐标（z 视为 0） */
const screenToWorldY = (my, cam, H) => (my - H * .5) / YSQUASH + cam.y;
/** 圆-矩形 相交（世界平面） */
function circleRect(cx, cy, r, rx, ry, rw, rh) {
	const nx = clamp(cx, rx, rx + rw);
	const ny = clamp(cy, ry, ry + rh);
	return dist2(cx, cy, nx, ny) < r * r;
}
/** 把圆推出矩形（简单分离） */
function pushOutRect(cx, cy, r, rx, ry, rw, rh) {
	const nx = clamp(cx, rx, rx + rw);
	const ny = clamp(cy, ry, ry + rh);
	let dx = cx - nx, dy = cy - ny;
	let d = Math.hypot(dx, dy);
	if (d > r) return [cx, cy];
	if (d < 1e-4) {
		const left = cx - rx, right = rx + rw - cx, top = cy - ry, bottom = ry + rh - cy;
		const m = Math.min(left, right, top, bottom);
		if (m === left) return [rx - r, cy];
		if (m === right) return [rx + rw + r, cy];
		if (m === top) return [cx, ry - r];
		return [cx, ry + rh + r];
	}
	dx /= d;
	dy /= d;
	return [nx + dx * r, ny + dy * r];
}
