//#region src/core/audio.ts
var SoundSystem = class {
	ctx = null;
	master = null;
	sfxGain = null;
	musicGain = null;
	volMaster = .75;
	volSfx = .9;
	volMusic = .5;
	muted = false;
	noiseBuf = null;
	droneNodes = null;
	musicOn = false;
	beatTimer = 0;
	beatIndex = 0;
	level = 0;
	/** 必须在用户手势后调用 */
	ensure() {
		if (this.ctx) {
			if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
			return;
		}
		try {
			const AC = window.AudioContext || window.webkitAudioContext;
			if (!AC) return;
			this.ctx = new AC();
			this.master = this.ctx.createGain();
			this.master.gain.value = this.muted ? 0 : this.volMaster;
			this.master.connect(this.ctx.destination);
			this.sfxGain = this.ctx.createGain();
			this.sfxGain.gain.value = this.volSfx;
			this.sfxGain.connect(this.master);
			this.musicGain = this.ctx.createGain();
			this.musicGain.gain.value = this.volMusic;
			this.musicGain.connect(this.master);
			const len = Math.floor(this.ctx.sampleRate * 1.2);
			const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
			const d = buf.getChannelData(0);
			for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
			this.noiseBuf = buf;
		} catch {}
	}
	setMasterVolume(v) {
		this.volMaster = v;
		this.muted = v <= .001;
		if (this.master && this.ctx) this.master.gain.setTargetAtTime(this.muted ? 0 : v, this.ctx.currentTime, .05);
	}
	toggleMute() {
		this.setMasterVolume(this.muted ? .75 : 0);
		return !this.muted;
	}
	tone(freq, dur, type, vol, opt = {}) {
		if (!this.ctx || !this.sfxGain) return;
		const t = this.ctx.currentTime;
		const osc = this.ctx.createOscillator();
		const g = this.ctx.createGain();
		osc.type = type;
		osc.frequency.setValueAtTime(Math.max(20, freq), t);
		if (opt.slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq * opt.slide), t + dur);
		if (opt.detune) osc.detune.value = opt.detune;
		const atk = opt.attack ?? .005;
		g.gain.setValueAtTime(1e-4, t);
		g.gain.exponentialRampToValueAtTime(Math.max(2e-4, vol), t + atk);
		g.gain.exponentialRampToValueAtTime(1e-4, t + dur);
		osc.connect(g);
		g.connect(opt.dest ?? this.sfxGain);
		osc.start(t);
		osc.stop(t + dur + .05);
	}
	noise(dur, vol, opt = {}) {
		if (!this.ctx || !this.sfxGain || !this.noiseBuf) return;
		const t = this.ctx.currentTime;
		const src = this.ctx.createBufferSource();
		src.buffer = this.noiseBuf;
		const f = this.ctx.createBiquadFilter();
		f.type = opt.type ?? "bandpass";
		f.frequency.setValueAtTime(opt.freq ?? 1200, t);
		if (opt.sweepTo) f.frequency.exponentialRampToValueAtTime(Math.max(60, opt.sweepTo), t + dur);
		f.Q.value = opt.q ?? 1.2;
		const g = this.ctx.createGain();
		g.gain.setValueAtTime(1e-4, t);
		g.gain.exponentialRampToValueAtTime(Math.max(2e-4, vol), t + (opt.attack ?? .006));
		g.gain.exponentialRampToValueAtTime(1e-4, t + dur);
		src.connect(f);
		f.connect(g);
		g.connect(this.sfxGain);
		src.start(t);
		src.stop(t + dur + .05);
	}
	sfx(name) {
		if (!this.ctx || this.muted) return;
		switch (name) {
			case "slash":
				this.noise(.16, .28, {
					freq: 2600,
					sweepTo: 500,
					q: .9
				});
				this.tone(680, .1, "triangle", .07, { slide: .5 });
				break;
			case "hit":
				this.noise(.1, .3, {
					freq: 420,
					sweepTo: 120,
					q: 1.4,
					type: "lowpass"
				});
				this.tone(180, .1, "square", .1, { slide: .6 });
				break;
			case "crit":
				this.noise(.2, .34, {
					freq: 900,
					sweepTo: 110,
					q: 1.1,
					type: "lowpass"
				});
				this.tone(880, .22, "sawtooth", .1, { slide: .28 });
				this.tone(1320, .16, "triangle", .07, { slide: .4 });
				break;
			case "coin":
				this.tone(1180, .09, "triangle", .11);
				this.tone(1760, .14, "triangle", .08, { attack: .01 });
				break;
			case "dash":
				this.noise(.22, .2, {
					freq: 300,
					sweepTo: 2200,
					q: .8,
					type: "bandpass"
				});
				break;
			case "skill":
				this.tone(220, .5, "sawtooth", .12, {
					slide: 3.2,
					attack: .02
				});
				this.tone(330, .45, "triangle", .08, { slide: 2.6 });
				this.noise(.5, .16, {
					freq: 400,
					sweepTo: 4200,
					q: .7
				});
				break;
			case "hurt":
				this.tone(160, .24, "square", .13, { slide: .45 });
				this.noise(.24, .22, {
					freq: 700,
					sweepTo: 160,
					q: .8,
					type: "lowpass"
				});
				break;
			case "light":
				[
					523,
					659,
					784,
					1046
				].forEach((f, i) => setTimeout(() => this.tone(f, .7, "triangle", .09, { attack: .02 }), i * 90));
				break;
			case "brazier":
				this.noise(.5, .2, {
					freq: 800,
					sweepTo: 2600,
					q: .6
				});
				this.tone(392, .8, "sine", .09, { attack: .04 });
				break;
			case "ui":
				this.tone(520, .06, "square", .05);
				break;
			case "uiBig":
				this.tone(300, .3, "triangle", .1, { slide: 1.8 });
				break;
			case "roar":
				this.tone(70, 1, "sawtooth", .2, {
					slide: .6,
					attack: .06
				});
				this.noise(1.1, .22, {
					freq: 260,
					sweepTo: 90,
					q: .6,
					type: "lowpass"
				});
				break;
			case "die":
				this.tone(200, 1.2, "sawtooth", .16, {
					slide: .2,
					attack: .02
				});
				this.tone(300, 1.1, "triangle", .1, { slide: .22 });
				break;
			case "save":
				[
					392,
					523,
					784
				].forEach((f, i) => setTimeout(() => this.tone(f, .9, "sine", .1, { attack: .05 }), i * 140));
				break;
			case "levelup": [
				523,
				622,
				784,
				1046,
				1318
			].forEach((f, i) => setTimeout(() => this.tone(f, .6, "triangle", .09), i * 80));
		}
	}
	startMusic(levelIndex) {
		if (!this.ctx || !this.musicGain) return;
		this.stopMusic();
		this.level = levelIndex;
		this.musicOn = true;
		this.beatTimer = 0;
		this.beatIndex = 0;
		const t = this.ctx.currentTime;
		const filter = this.ctx.createBiquadFilter();
		filter.type = "lowpass";
		filter.frequency.value = 420;
		filter.Q.value = 2;
		const g = this.ctx.createGain();
		g.gain.setValueAtTime(1e-4, t);
		g.gain.exponentialRampToValueAtTime(.25, t + 3.5);
		g.connect(filter);
		filter.connect(this.musicGain);
		const roots = [
			110,
			87.31,
			98
		];
		const root = roots[clampIdx(levelIndex, 0, roots.length - 1)];
		const oscs = [];
		[
			{
				f: root,
				type: "sawtooth",
				det: -6,
				vol: .5
			},
			{
				f: root,
				type: "sawtooth",
				det: 7,
				vol: .4
			},
			{
				f: root * 1.5,
				type: "sine",
				det: 0,
				vol: .35
			},
			{
				f: root * .5,
				type: "sine",
				det: 0,
				vol: .5
			}
		].forEach((o) => {
			const osc = this.ctx.createOscillator();
			osc.type = o.type;
			osc.frequency.value = o.f;
			osc.detune.value = o.det;
			const og = this.ctx.createGain();
			og.gain.value = o.vol;
			osc.connect(og);
			og.connect(g);
			osc.start(t);
			oscs.push(osc);
		});
		this.droneNodes = {
			osc: oscs,
			gain: g,
			filter
		};
	}
	stopMusic() {
		if (!this.ctx || !this.droneNodes) return;
		const t = this.ctx.currentTime;
		const { osc, gain } = this.droneNodes;
		gain.gain.cancelScheduledValues(t);
		gain.gain.setTargetAtTime(1e-4, t, .4);
		osc.forEach((o) => {
			try {
				o.stop(t + 2);
			} catch {}
		});
		this.droneNodes = null;
		this.musicOn = false;
	}
	/** 每帧调用；intensity 0..1 由连击/亮度驱动 */
	updateMusic(dt, intensity) {
		if (!this.ctx || !this.musicOn || this.muted) return;
		if (this.droneNodes) this.droneNodes.filter.frequency.setTargetAtTime(340 + intensity * 1100, this.ctx.currentTime, .4);
		const interval = lerpNum(1.25, .36, clamp01(intensity));
		this.beatTimer += dt;
		if (this.beatTimer < interval) return;
		this.beatTimer -= interval;
		this.beatIndex++;
		const scales = [
			[
				0,
				3,
				5,
				7,
				10
			],
			[
				0,
				1,
				5,
				6,
				8
			],
			[
				0,
				2,
				3,
				7,
				9
			]
		];
		const root = [
			220,
			174.61,
			196
		][clampIdx(this.level, 0, 2)];
		const scale = scales[clampIdx(this.level, 0, 2)];
		const semi = scale[Math.floor(Math.random() * scale.length)] + (Math.random() < .25 ? 12 : 0);
		const f = root * Math.pow(2, semi / 12);
		this.tone(f, 1.6, "triangle", .05 + intensity * .05, { attack: .02 });
		if (this.beatIndex % 4 === 0) this.tone(root * .5, .5, "sine", .1 + intensity * .08, { slide: .6 });
		if (intensity > .55 && this.beatIndex % 2 === 1) this.noise(.1, .06, {
			freq: 5200,
			q: .9
		});
	}
};
const clamp01 = (v) => v < 0 ? 0 : v > 1 ? 1 : v;
const lerpNum = (a, b, t) => a + (b - a) * t;
const clampIdx = (v, a, b) => v < a ? a : v > b ? b : v;
