/** 精英化：相当于该关卡的"精英怪" */
function eliteify(def) {
	return {
		...def,
		name: def.name + "（精英）",
		hp: Math.round(def.hp * 2.6),
		dmg: Math.round(def.dmg * 1.35),
		r: def.r * 1.28,
		h: def.h * 1.2,
		coin: Math.round(def.coin * 4),
		glow: "#ffe08a",
		light: (def.light ?? 0) + 34,
		weight: 1
	};
}
