const B = 44;
/** 生成外圈边界墙 */
function border(w, h, ht) {
	return [
		{
			x: 0,
			y: 0,
			w,
			d: B,
			h: ht
		},
		{
			x: 0,
			y: h - B,
			w,
			d: B,
			h: ht
		},
		{
			x: 0,
			y: 0,
			w: B,
			d: h,
			h: ht
		},
		{
			x: w - B,
			y: 0,
			w: B,
			d: h,
			h: ht
		}
	];
}
