for (const w of WEAPONS) check(`【${w.name}】技能连击门槛递增且为正（README：技能需要连击数解锁）`, w.skills.every((s) => s.cost > 0) && w.skills.every((s, i, a) => i === 0 || s.cost > a[i - 1].cost), w.skills.map((s) => `${s.name}:${s.cost}`).join(" "));
check("三把武器的技能数量各不相同（README 要求）", new Set(WEAPONS.map((w) => w.skills.length)).size === WEAPONS.length, WEAPONS.map((w) => `${w.name}(${w.skills.length})`).join(" "));
check("武器表可查询", !!WEAPON_MAP["blade"] && !!WEAPON_MAP["spear"] && !!WEAPON_MAP["hammer"]);
check("三关都有 Boss、终点与光照参数", LEVELS.every((l) => !!l.boss.type && !!l.goal.kind && l.ambient > .5));
check("灯芯升级会同时作用于血量与亮度", (() => {
	const a = new World(0, newProgress());
	const p2 = newProgress();
	p2.up = {
		hp: 6,
		light: 5,
		edge: 0
	};
	p2.shop = {
		ember: 2,
		brightoil: 2
	};
	const b2 = new World(0, p2);
	return b2.lightRadius > a.lightRadius && b2.player.maxHp > a.player.maxHp;
})());
console.log(`\n${failures === 0 ? "全部通过 ✅" : `有 ${failures} 项未通过 ❌`}`);
process.exit(failures === 0 ? 0 : 1);
//#endregion
export {};
